#### Example 3: Tenant Context-Aware Extension Slot

_[To be completed]_

```typescript
// Extension slot that loads tenant-specific micro-frontends
import { useTenantContext } from '@gainwell/extensions-sdk-react';

export const TenantExtensionSlot: React.FC<TenantExtensionSlotProps> = ({
  slotName,
  fallback
}) => {
  const { tenantId } = useTenantContext();
  const { mfes, loading } = useTenantMicroFrontends(tenantId);

  if (loading) {
    return <LoadingSpinner />;
  }

  const MFEComponent = mfes.get(slotName);

  if (!MFEComponent) {
    return fallback || null;
  }

  return (
    <ErrorBoundary fallback={<ExtensionError />}>
      <MFEComponent tenantId={tenantId} />
    </ErrorBoundary>
  );
};
```

