#### Example 5: Tenant MFE Caching Strategy

_[To be completed]_

```typescript
// Caching strategy for tenant micro-frontends
class TenantMFECache {
  private cache: Map<string, React.ComponentType> = new Map();
  private loadingCache: Map<string, Promise<React.ComponentType>> = new Map();

  async getOrLoad(
    tenantId: string,
    mfeName: string,
    loader: () => Promise<React.ComponentType>
  ): Promise<React.ComponentType> {
    const cacheKey = `${tenantId}:${mfeName}`;

    // Return from cache if available
    if (this.cache.has(cacheKey)) {
      return this.cache.get(cacheKey)!;
    }

    // Return in-flight loading promise
    if (this.loadingCache.has(cacheKey)) {
      return this.loadingCache.get(cacheKey)!;
    }

    // Load and cache
    const loadingPromise = loader().then(component => {
      this.cache.set(cacheKey, component);
      this.loadingCache.delete(cacheKey);
      return component;
    });

    this.loadingCache.set(cacheKey, loadingPromise);
    return loadingPromise;
  }

  clear(tenantId?: string) {
    if (tenantId) {
      // Clear specific tenant's cache
      const prefix = `${tenantId}:`;
      for (const key of this.cache.keys()) {
        if (key.startsWith(prefix)) {
          this.cache.delete(key);
        }
      }
    } else {
      // Clear all cache
      this.cache.clear();
      this.loadingCache.clear();
    }
  }
}

export const tenantMFECache = new TenantMFECache();
